INSERT IGNORE INTO schedule_clone_batches (reference_no, schedule_name, schedule_type, source_section_id, target_section_id, source_academic_year, source_semester, target_academic_year, target_semester, options_json, status, cloned_count, validated_at, created_by, created_at) SELECT 'CLN-2026-0001', 'BSIT 1-A 2nd Semester schedule (from AY 2025-2026)', 'Regular', src.id, dst.id, '2025-2026', '2nd Semester', '2026-2027', '2nd Semester', '{"copy_subjects":true,"copy_time_slots":true,"copy_faculty":true,"copy_rooms":true,"copy_class_types":true}', 'Validated', 6, '2026-09-25 16:12:00', (SELECT id FROM users WHERE username = 'registrar' LIMIT 1), '2026-09-25 16:05:00' FROM sections src, sections dst WHERE src.code = 'BSIT-1A' AND src.academic_year = '2025-2026' AND src.semester = '2nd Semester' AND dst.code = 'BSIT-1A' AND dst.academic_year = '2026-2027' AND dst.semester = '2nd Semester';
INSERT IGNORE INTO schedule_clone_batch_entries (clone_batch_id, source_entry_id, cloned_entry_id) SELECT b.id, s.id, c.id FROM schedule_clone_batches b JOIN schedule_entries s ON s.section_id = b.source_section_id AND s.academic_year = b.source_academic_year AND s.semester = b.source_semester JOIN schedule_entries c ON c.section_id = b.target_section_id AND c.academic_year = b.target_academic_year AND c.semester = b.target_semester  AND c.subject_id = s.subject_id AND c.day_of_week = s.day_of_week AND c.start_time = s.start_time WHERE b.reference_no = 'CLN-2026-0001';
INSERT INTO schedule_clone_history (clone_batch_id, action, from_status, to_status, detail, changed_by, changed_at) SELECT id, 'Clone preview generated', NULL, 'Draft', 'Previewed 6 classes with subjects, time slots, faculty, rooms and class types copied.', (SELECT id FROM users WHERE username = 'registrar' LIMIT 1), '2026-09-25 16:05:00' FROM schedule_clone_batches WHERE reference_no = 'CLN-2026-0001';
INSERT INTO schedule_clone_history (clone_batch_id, action, from_status, to_status, detail, changed_by, changed_at) SELECT id, 'Draft schedule created', 'Draft', 'Draft', '6 draft classes created for BSIT 1-A, AY 2026-2027 2nd Semester.', (SELECT id FROM users WHERE username = 'registrar' LIMIT 1), '2026-09-25 16:06:00' FROM schedule_clone_batches WHERE reference_no = 'CLN-2026-0001';
